-- LOCAL disposable PostgreSQL only; runner wraps everything in ROLLBACK. No provider.
reset role;
select m83_assert(not exists(select data from cost_legacy_requests except select to_jsonb(r)-array['action_operation_id','commercial_operation_id','measurement_version'] from public.ai_requests r),'migration preserves historical requests without invented backfill');
select m83_assert(not exists(select data from cost_legacy_events except select to_jsonb(e)-'measurement' from public.ai_usage_events e),'migration preserves historical costs and token counts');
select m83_assert(not exists(select 1 from public.ai_usage_events where measurement is not null),'no invented historical provider detail');
create temp table cost_state(key text primary key,value jsonb);grant all on cost_state to authenticated,service_role;
create function public.cost_req(fn text,op text,org uuid) returns jsonb language sql as $$select public.record_ai_history_v1('open_request',jsonb_build_object('scope',case when org is null then 'platform' else 'organization' end,'organizationId',org,'functionName',fn,'operationId',m83_id(op),'sourceVersion','fixture-1.0.0','inputFingerprint',repeat('a',64),'idempotencyKey',encode(sha256(convert_to(op,'UTF8')),'hex')))$$;
insert into cost_state values('measurement','{"version":"ai-cost-measurement-1.0.0","requestedModel":"gpt-5.6-luna","resolvedModel":"gpt-5.6-luna","providerResponseId":"resp_synthetic","providerRequestId":"req_synthetic","serviceTier":"default","inputCachedTokens":0,"inputCacheWriteTokens":0,"outputReasoningTokens":0,"webSearchCalls":0,"otherToolCalls":0,"calculationStatus":"calculated","lowerBoundUsd":0.000044,"upperBoundUsd":0.000044,"tokenCostUsd":0.000044,"toolCostUsd":0}');
select m83_assert(not private.ai_cost_measurement_valid((select value||'{"prompt":"private forbidden"}' from cost_state where key='measurement')),'metadata rejects prompt or arbitrary nested fields');
select m83_assert(not private.ai_cost_measurement_valid('{"version":"ai-cost-measurement-1.0.0","calculationStatus":"calculated"}'),'metadata requires complete declared shape, including nullable fields');
set local role anon;
select m83_reject('select public.ai_cost_history_v1()','42501');
select m83_reject('select public.record_ai_history_v1(''open_request'',''{}'')','42501');
reset role;set local role authenticated;
select set_config('request.jwt.claim.sub',m83_id('super')::text,true);
select m83_assert(public.ai_cost_history_v1()->>'contract'='ai-action-cost-report-1.0.0','active super can read internal report');
select m83_reject('select public.ai_cost_history_v1(51)','22023');
select m83_reject('select public.ai_cost_history_v1(25,now(),null)','22023');
select m83_reject('select public.record_ai_history_v1(''open_request'',''{}'')','42501');
select set_config('request.jwt.claim.sub',m83_id('owner')::text,true);
select m83_reject('select public.ai_cost_history_v1()','42501');
select set_config('request.jwt.claim.sub',m83_id('recruiter')::text,true);
select m83_reject('select public.ai_cost_history_v1()','42501');
select set_config('request.jwt.claim.sub',m83_id('member')::text,true);
select m83_reject('select public.ai_cost_history_v1()','42501');
reset role;
update public.platform_users set status='inactive' where auth_user_id=m83_id('super');
set local role authenticated;select set_config('request.jwt.claim.sub',m83_id('super')::text,true);
select m83_reject('select public.ai_cost_history_v1()','42501');
reset role;update public.platform_users set status='active' where auth_user_id=m83_id('super');

-- Separate synthetic company: mixed monthly/additional allocation, no real order or invoice.
insert into public.organizations(id,name,group_id) values(m83_id('cost-company'),'Cost synthetic',m83_id('group'));
insert into public.organization_memberships(organization_id,user_id,role) values(m83_id('cost-company'),m83_id('owner'),'owner') on conflict(organization_id,user_id) do nothing;
select private.prisma_token_ensure(m83_id('cost-company'));
update private.prisma_token_lots set remaining=100 where organization_id=m83_id('cost-company') and source='monthly';
insert into private.prisma_token_lots(organization_id,source,source_key,total,remaining,expires_at) values(m83_id('cost-company'),'additional','synthetic-paid-lot',100000,100000,now()+interval '1 month');
set local role authenticated;select set_config('request.jwt.claim.sub',m83_id('owner')::text,true);
insert into cost_state values('quote',public.prisma_tokens('quote',m83_id('cost-company'),'{"functionName":"parser_ia","quantity":1}'));
reset role;select private.prisma_token_reserve(m83_id('cost-company'),'parser_ia',m83_id('cost-parser'),(select (value->>'id')::uuid from cost_state where key='quote'),1);
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into cost_state values('parser',public.cost_req('parser_ia','cost-parser',m83_id('cost-company')));
do $$declare r uuid:=(select (value#>>'{request,id}')::uuid from cost_state where key='parser');m jsonb:=(select value from cost_state where key='measurement');i int;v jsonb;begin
 for i in 1..2 loop
  v:=public.record_ai_history_v1('begin_attempt',jsonb_build_object('requestId',r,'organizationId',m83_id('cost-company'),'attemptId',m83_id('cost-attempt-'||i),'stage','provider','provider','openai-responses','model','gpt-5.6-luna','methodVersion','fixture-1.0.0','usageKind','external','pricingVersion','openai-standard-2026-10-18'));
  perform m83_assert(v->>'acquired'='true','new attempt acquires exactly once');
  v:=public.record_ai_history_v1('complete_attempt',jsonb_build_object('requestId',r,'organizationId',m83_id('cost-company'),'attemptId',m83_id('cost-attempt-'||i),'result',case when i=1 then 'failure' else 'success' end,'durationMs',10,'inputTokens',100,'outputTokens',20,'estimatedCostUsd',0.000044,'observedCostUsd',null,'costEvidenceHash',null,'errorCategory',case when i=1 then 'RESPONSE_INVALID' else null end,'measurement',m));
  perform m83_assert(v->>'recorded'='true','failed/success usage recorded');
  v:=public.record_ai_history_v1('complete_attempt',jsonb_build_object('requestId',r,'organizationId',m83_id('cost-company'),'attemptId',m83_id('cost-attempt-'||i),'result',case when i=1 then 'failure' else 'success' end,'durationMs',10,'inputTokens',100,'outputTokens',20,'estimatedCostUsd',0.000044,'observedCostUsd',null,'costEvidenceHash',null,'errorCategory',case when i=1 then 'RESPONSE_INVALID' else null end,'measurement',m));
  perform m83_assert(v->>'recorded'='false','same metadata replay is idempotent');
 end loop;
 perform public.record_ai_history_v1('complete_request',jsonb_build_object('requestId',r,'organizationId',m83_id('cost-company'),'status','succeeded','errorCategory',null));
end $$;
reset role;
select private.prisma_token_settle(m83_id('cost-company'),'parser_ia',m83_id('cost-parser'),true);
create temp table cost_preserve as select (select jsonb_agg(to_jsonb(s) order by id) from private.prisma_token_reservations s) reservations,(select jsonb_agg(to_jsonb(s) order by id) from private.prisma_token_movements s) movements;
set local role authenticated;select set_config('request.jwt.claim.sub',m83_id('super')::text,true);select set_config('request.jwt.claims','{"role":"authenticated"}',true);
insert into cost_state select 'report',public.ai_cost_history_v1(25,null,null,'parser_ia',m83_id('cost-company'));
select m83_assert((select value#>>'{items,0,usage,attemptCount}'='2' and (value#>>'{items,0,usage,estimatedUsd}')::numeric=0.000088 from cost_state where key='report'),'one action sums successful and failed provider attempts');
select m83_assert((select value#>>'{items,0,commercial,reservations,0,quantity}'='1' and jsonb_array_length(value#>'{items,0,commercial,reservations}')=1 and value#>>'{items,0,commercial,debitedTokens}'=(select value->>'amount' from cost_state where key='quote') from cost_state where key='report'),'commercial reservation counted once, independently of two API attempts');
select m83_assert((select jsonb_array_length(value#>'{items,0,commercial,reservations,0,sources}')=2 from cost_state where key='report'),'monthly and additional origins preserved');
select m83_assert((select value#>>'{items,0,usage,observedUsd}' is null from cost_state where key='report'),'calculated costs are not declared reconciled');
select m83_assert((select jsonb_array_length(public.ai_cost_history_v1(25,null,null,null,m83_id('b'))->'items')=count(*) from public.ai_requests where organization_id=m83_id('b')),'company filter does not mix tenant metadata');
select m83_assert(jsonb_array_length(public.ai_cost_history_v1(25,null,null,null,null,(select (value#>>'{items,0,actionId}')::uuid from cost_state where key='report'))#>'{items,0,requests,0,attempts}')=2,'detail exposes each request and provider attempt');
reset role;
select m83_assert((select reservations=(select jsonb_agg(to_jsonb(s) order by id) from private.prisma_token_reservations s) and movements=(select jsonb_agg(to_jsonb(s) order by id) from private.prisma_token_movements s) from cost_preserve),'report is read-only and cannot settle or charge');

-- Internal/platform operations cost API money without debiting commercial tokens.
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into cost_state values('internal',public.cost_req('knowledge_concept_description','cost-internal',null));
select public.record_ai_history_v1('begin_attempt',jsonb_build_object('requestId',(select value#>>'{request,id}' from cost_state where key='internal'),'organizationId',null,'attemptId',m83_id('cost-unknown'),'stage','provider','provider','openai-responses','model','gpt-5.6-luna','methodVersion','fixture','usageKind','external','pricingVersion','openai-standard-2026-10-18'));
select public.record_ai_history_v1('complete_attempt',jsonb_build_object('requestId',(select value#>>'{request,id}' from cost_state where key='internal'),'organizationId',null,'attemptId',m83_id('cost-unknown'),'result','failure','durationMs',10,'inputTokens',null,'outputTokens',null,'estimatedCostUsd',null,'observedCostUsd',null,'costEvidenceHash',null,'errorCategory','PROVIDER_TIMEOUT'));
reset role;set local role authenticated;select set_config('request.jwt.claim.sub',m83_id('super')::text,true);
select m83_assert((public.ai_cost_history_v1(25,null,null,'knowledge_concept_description')#>>'{items,0,commercial,debitedTokens}')::integer=0 and public.ai_cost_history_v1(25,null,null,'knowledge_concept_description')#>>'{items,0,commercial,state}'='included','internal function has explicit zero customer debit');
select m83_assert(public.ai_cost_history_v1(25,null,null,'knowledge_concept_description')#>>'{items,0,usage,estimatedUsd}' is null and public.ai_cost_history_v1(25,null,null,'knowledge_concept_description')#>>'{items,0,usage,unknownAttempts}'='1','failed timeout remains unknown instead of zero');
select m83_assert(public.ai_cost_history_v1(1)->>'hasMore'='true','bounded first page reports more actions');
insert into cost_state values('page',public.ai_cost_history_v1(1));
select m83_assert(public.ai_cost_history_v1(1,(select (value#>>'{items,0,latestAt}')::timestamptz from cost_state where key='page'),(select (value#>>'{items,0,actionId}')::uuid from cost_state where key='page'))#>>'{items,0,actionId}'<>(select value#>>'{items,0,actionId}' from cost_state where key='page'),'keyset pagination advances without repeating the boundary');
reset role;

-- Stable synthesis job groups successive leases; commercial binding is captured, never read retrospectively from a mutable job binding.
update private.prisma_token_accounts set active=true where organization_id=m83_id('a');
insert into public.profile_synthesis_jobs(id,organization_id,person_id,profile_id,basis_hash,state,lease,lease_until) values(m83_id('cost-synth-job'),m83_id('a'),m83_id('person'),m83_id('profile'),repeat('e',64),'processing',m83_id('cost-lease-1'),now()+interval '1 hour');
set local role authenticated;select set_config('request.jwt.claim.sub',m83_id('owner')::text,true);
insert into cost_state values('synth-quote',public.prisma_tokens('quote',m83_id('a'),'{"functionName":"profile_synthesis","quantity":1}'));
reset role;
insert into private.prisma_synthesis_token_bindings(job_id,organization_id,operation_id,quote_id) select m83_id('cost-synth-job'),m83_id('a'),(value->>'id')::uuid,(value->>'id')::uuid from cost_state where key='synth-quote';
select private.prisma_token_reserve(m83_id('a'),'profile_synthesis',(select (value->>'id')::uuid from cost_state where key='synth-quote'),(select (value->>'id')::uuid from cost_state where key='synth-quote'),1);
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
insert into cost_state values('synth1',public.cost_req('profile_synthesis','cost-lease-1',m83_id('a')));
reset role;update public.profile_synthesis_jobs set lease=m83_id('cost-lease-2') where id=m83_id('cost-synth-job');
set local role service_role;
insert into cost_state values('synth2',public.cost_req('profile_synthesis','cost-lease-2',m83_id('a')));
reset role;
select m83_assert((select count(distinct action_operation_id)=1 and count(distinct commercial_operation_id)=1 from public.ai_requests where operation_id in(m83_id('cost-lease-1'),m83_id('cost-lease-2'))),'two synthesis leases map to one stable action and one commercial reservation');
update private.prisma_synthesis_token_bindings set operation_id=m83_id('later-explicit-operation') where job_id=m83_id('cost-synth-job');
set local role service_role;
select public.cost_req('profile_synthesis','cost-lease-1',m83_id('a'));
reset role;
select m83_assert((select bool_and(commercial_operation_id=(select (value->>'id')::uuid from cost_state where key='synth-quote')) from public.ai_requests where operation_id in(m83_id('cost-lease-1'),m83_id('cost-lease-2'))),'replay after lease/binding change preserves original quote linkage');
set local role authenticated;select set_config('request.jwt.claim.sub',m83_id('super')::text,true);
select m83_assert(public.ai_cost_history_v1(25,null,null,'profile_synthesis',m83_id('a'))#>>'{items,0,requestCount}'='2' and jsonb_array_length(public.ai_cost_history_v1(25,null,null,'profile_synthesis',m83_id('a'))#>'{items,0,commercial,reservations}')=1,'action aggregation does not multiply one reservation across requests');
reset role;
set local role service_role;
select m83_reject(format('select public.record_ai_history_v1(''open_request'',%L)',jsonb_build_object('scope','organization','organizationId',m83_id('b'),'functionName','profile_synthesis','operationId',m83_id('cost-cross-job'),'actionOperationId',m83_id('cost-synth-job'),'sourceVersion','fixture','inputFingerprint',repeat('a',64),'idempotencyKey',repeat('9',64))),'42501');
select m83_reject(format('select public.record_ai_history_v1(''complete_attempt'',%L)',jsonb_build_object('requestId',(select value#>>'{request,id}' from cost_state where key='parser'),'organizationId',m83_id('b'),'attemptId',m83_id('cost-attempt-1'),'measurement',(select value from cost_state where key='measurement'))),'42501');
select m83_reject(format('select public.record_ai_history_v1(''complete_attempt'',%L)',jsonb_build_object('requestId',(select value#>>'{request,id}' from cost_state where key='parser'),'organizationId',m83_id('cost-company'),'attemptId',m83_id('cost-attempt-1'),'result','failure','durationMs',10,'inputTokens',100,'outputTokens',20,'estimatedCostUsd',0.000044,'observedCostUsd',null,'costEvidenceHash',null,'errorCategory','RESPONSE_INVALID','measurement',(select value||'{"providerResponseId":"resp_other"}' from cost_state where key='measurement'))),'40001');
insert into cost_state values('paged',public.cost_req('knowledge_research','cost-paged',null));
do $$declare r uuid:=(select (value#>>'{request,id}')::uuid from cost_state where key='paged');i int;begin
 for i in 1..60 loop
  perform public.record_ai_history_v1('begin_attempt',jsonb_build_object('requestId',r,'organizationId',null,'attemptId',m83_id('cache-'||i),'stage','cache','provider','cache','model','none','methodVersion','fixture','usageKind','cache','pricingVersion',null));
  perform public.record_ai_history_v1('complete_attempt',jsonb_build_object('requestId',r,'organizationId',null,'attemptId',m83_id('cache-'||i),'result','success','durationMs',1,'inputTokens',null,'outputTokens',null,'estimatedCostUsd',0,'observedCostUsd',0,'costEvidenceHash',null,'errorCategory',null));
 end loop;
end $$;
reset role;set local role authenticated;select set_config('request.jwt.claim.sub',m83_id('super')::text,true);
insert into cost_state values('paged-action',public.ai_cost_history_v1(25,null,null,'knowledge_research'));
insert into cost_state select 'attempt-page',public.ai_cost_history_v1(25,null,null,null,null,(value#>>'{items,0,actionId}')::uuid) from cost_state where key='paged-action';
select m83_assert((select value->>'hasMoreAttempts'='true' and jsonb_array_length(value#>'{items,0,requests,0,attempts}')=50 and value#>>'{items,0,usage,attemptCount}'='60' from cost_state where key='attempt-page'),'detail is bounded at 50 attempts while totals cover all 60');
select m83_assert((select jsonb_array_length(public.ai_cost_history_v1(25,null,null,null,null,(value#>>'{items,0,actionId}')::uuid,(value->>'nextAttemptId')::bigint)#>'{items,0,requests,0,attempts}')=10 from cost_state where key='attempt-page'),'detail resumes remaining attempts with keyset cursor');
reset role;
-- New activity completion attaches metadata atomically; an old receipt cannot be enriched by replay.
set local role authenticated;select set_config('request.jwt.claim.sub',m83_id('recruiter')::text,true);select set_config('request.headers','{"x-prisma-activity-method":"assessment-activity-analysis-1.1.0"}',true);
insert into cost_state values('activity-quote',public.prisma_tokens('quote',m83_id('a'),'{"functionName":"assessment_activity_analysis","quantity":1}'));
insert into cost_state values('activity-start',public.assessment_activity_analysis_start(m83_id('a'),m83_id('aa-attempt'),m83_id('cost-activity'),(select (value->>'id')::uuid from cost_state where key='activity-quote')));
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select public.assessment_activity_analysis_finish(m83_id('a'),m83_id('cost-activity'),false,null,null,jsonb_build_object('durationMs',10,'inputTokens',100,'outputTokens',20,'estimatedCostUsd',0.000044,'measurement',(select value from cost_state where key='measurement')));
select public.assessment_activity_analysis_finish(m83_id('a'),m83_id('cost-activity'),false,null,null,jsonb_build_object('durationMs',10,'inputTokens',100,'outputTokens',20,'estimatedCostUsd',0.000044,'measurement',(select value from cost_state where key='measurement')));
reset role;
select m83_assert(exists(select 1 from public.ai_usage_events e join public.ai_requests r on r.id=e.request_id where r.operation_id=m83_id('cost-activity') and e.measurement is not null and e.pricing_version='openai-standard-2026-10-18' and e.estimated_cost_usd=0.000044),'activity metadata/cost preserved with its transactional completion');
select m83_assert(exists(select 1 from private.prisma_token_reservations where operation_id=m83_id('cost-activity') and status='released'),'failed activity still releases customer tokens and retains provider cost');
set local role service_role;select set_config('request.jwt.claims','{"role":"service_role"}',true);
select m83_reject(format('select public.assessment_activity_analysis_finish(%L,%L,false,null,null,%L)',m83_id('a'),m83_id('aa-after-release'),jsonb_build_object('durationMs',10,'inputTokens',100,'outputTokens',20,'estimatedCostUsd',0.000044,'measurement',(select value from cost_state where key='measurement'))),'40001');
reset role;
select m83_assert(exists(select 1 from public.ai_requests where operation_id=m83_id('cost-activity') and measurement_version='ai-action-cost-metering-1.0.0' and commercial_operation_id=m83_id('cost-activity')),'activity start uses rebound writer and captures its commercial operation');
-- Actual restricted worker boundary: quoted provider attempt and unquoted local-cache reuse.
set local role authenticated;select set_config('request.jwt.claim.sub',m83_id('owner')::text,true);
insert into cost_state values('worker-quote',public.prisma_tokens('quote',m83_id('cost-company'),'{"functionName":"parser_ia","quantity":1}'));
insert into cost_state values('worker',public.record_ai_worker_history_v1(repeat('h',64),'open_request',jsonb_build_object('scope','organization','organizationId',m83_id('cost-company'),'functionName','parser_ia','operationId',m83_id('cost-worker'),'sourceVersion','fixture','inputFingerprint',repeat('b',64),'idempotencyKey',repeat('7',64),'tokenQuoteId',(select value->>'id' from cost_state where key='worker-quote'))));
select public.record_ai_worker_history_v1(repeat('h',64),'begin_attempt',jsonb_build_object('requestId',(select value#>>'{request,id}' from cost_state where key='worker'),'organizationId',m83_id('cost-company'),'attemptId',m83_id('cost-worker-attempt'),'stage','provider','provider','openai-responses','model','gpt-5.6-luna','methodVersion','fixture','usageKind','external','pricingVersion','openai-standard-2026-10-18'));
select public.record_ai_worker_history_v1(repeat('h',64),'complete_attempt',jsonb_build_object('requestId',(select value#>>'{request,id}' from cost_state where key='worker'),'organizationId',m83_id('cost-company'),'attemptId',m83_id('cost-worker-attempt'),'result','failure','durationMs',10,'inputTokens',100,'outputTokens',20,'estimatedCostUsd',0.000044,'observedCostUsd',null,'costEvidenceHash',null,'errorCategory','RESPONSE_INVALID','measurement',(select value from cost_state where key='measurement')));
select public.record_ai_worker_history_v1(repeat('h',64),'complete_request',jsonb_build_object('requestId',(select value#>>'{request,id}' from cost_state where key='worker'),'organizationId',m83_id('cost-company'),'status','failed','errorCategory','RESPONSE_INVALID'));
insert into cost_state values('new-cache',public.record_ai_worker_history_v1(repeat('h',64),'open_request',jsonb_build_object('scope','organization','organizationId',m83_id('cost-company'),'functionName','parser_ia','operationId',m83_id('cost-new-cache'),'sourceVersion','fixture','inputFingerprint',repeat('b',64),'idempotencyKey',repeat('8',64))));
select public.record_ai_worker_history_v1(repeat('h',64),'begin_attempt',jsonb_build_object('requestId',(select value#>>'{request,id}' from cost_state where key='new-cache'),'organizationId',m83_id('cost-company'),'attemptId',m83_id('cost-cache-attempt'),'stage','cache','provider','cache','model','none','methodVersion','fixture','usageKind','cache','pricingVersion',null));
select public.record_ai_worker_history_v1(repeat('h',64),'complete_attempt',jsonb_build_object('requestId',(select value#>>'{request,id}' from cost_state where key='new-cache'),'organizationId',m83_id('cost-company'),'attemptId',m83_id('cost-cache-attempt'),'result','success','durationMs',1,'inputTokens',null,'outputTokens',null,'estimatedCostUsd',0,'observedCostUsd',0,'costEvidenceHash',null,'errorCategory',null));
select public.record_ai_worker_history_v1(repeat('h',64),'complete_request',jsonb_build_object('requestId',(select value#>>'{request,id}' from cost_state where key='new-cache'),'organizationId',m83_id('cost-company'),'status','succeeded','errorCategory',null));
select set_config('request.jwt.claim.sub',m83_id('super')::text,true);
select m83_assert(public.ai_cost_history_v1(25,null,null,'parser_ia',m83_id('cost-company'))#>>'{items,0,commercial,state}'='reused' and public.ai_cost_history_v1(25,null,null,'parser_ia',m83_id('cost-company'))#>>'{items,0,commercial,debitedTokens}'='0','quoted function served from cache has proven zero customer debit');
reset role;
select m83_assert(exists(select 1 from public.ai_requests r join public.ai_usage_events e on e.request_id=r.id join private.prisma_token_reservations s on s.operation_id=r.commercial_operation_id and s.organization_id=r.organization_id and s.function_name=r.function_name where r.operation_id=m83_id('cost-worker') and e.measurement is not null and s.status='released'),'restricted worker persists API cost and releases failed delivery without an extra debit');
